import { randomUUID } from "node:crypto";
import fs from "node:fs/promises";
import path from "node:path";

/**
 * Where file bytes are kept. Keys are generated by the application (`<schoolId>/<uuid>`) and
 * never contain user input. Only a local-disk driver exists today; an object-storage driver is
 * added when a hosting provider is chosen (local disk does not survive on serverless hosts).
 */
export interface FileStorage {
  readonly name: string;
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Buffer>;
  /** Succeeds if the key is already gone. */
  delete(key: string): Promise<void>;
}

const KEY_FORMAT = /^[0-9a-f-]{36}\/[0-9a-f-]{36}$/;

export function newStorageKey(schoolId: string): string {
  return `${schoolId}/${randomUUID()}`;
}

function assertKey(key: string): void {
  if (!KEY_FORMAT.test(key)) throw new Error("Invalid storage key");
}

export function localDiskStorage(baseDir: string): FileStorage {
  const root = path.resolve(baseDir);
  const resolve = (key: string) => {
    assertKey(key);
    const full = path.resolve(root, ...key.split("/"));
    if (!full.startsWith(root + path.sep)) throw new Error("Invalid storage key");
    return full;
  };
  return {
    name: "local",
    async put(key, data) {
      const full = resolve(key);
      await fs.mkdir(path.dirname(full), { recursive: true });
      // Write to a temporary name first so a crash never leaves a half-written file under the key.
      const tmp = `${full}.${randomUUID()}.tmp`;
      await fs.writeFile(tmp, data, { flag: "wx" });
      await fs.rename(tmp, full);
    },
    async get(key) {
      return fs.readFile(resolve(key));
    },
    async delete(key) {
      await fs.rm(resolve(key), { force: true });
    },
  };
}

/** FILE_STORAGE=local (default) with FILE_STORAGE_DIR (default `<repo>/.data/files`). */
export function fileStorageFromEnv(env: NodeJS.ProcessEnv, repoRoot: string): FileStorage {
  const driver = (env.FILE_STORAGE ?? "local").trim() || "local";
  if (driver !== "local") throw new Error(`FILE_STORAGE "${driver}" is not supported. Supported: local.`);
  return localDiskStorage(env.FILE_STORAGE_DIR?.trim() || path.join(repoRoot, ".data", "files"));
}
